typedef ssize_t (*readlinkat_fn)(int, const char *, char *, size_t);

static int is_current_pid_exe(const char *path) {
    char expected[64];
    int length;

    if (path == NULL) {
        return 0;
    }
    length = snprintf(
        expected, sizeof(expected), "/proc/%ld/exe", (long)getpid()
    );
    return length > 0
        && (size_t)length < sizeof(expected)
        && strcmp(path, expected) == 0;
}

ssize_t readlink(const char *path, char *buffer, size_t size) {
    static readlink_fn real_readlink = NULL;

    if (real_readlink == NULL) {
        real_readlink = (readlink_fn)dlsym(RTLD_NEXT, "readlink");
        if (real_readlink == NULL) {
            errno = ENOSYS;
            return -1;
        }
    }
    return real_readlink(
        is_current_pid_exe(path) ? "/proc/self/exe" : path,
        buffer,
        size
    );
}

ssize_t readlinkat(
    int directory_fd,
    const char *path,
    char *buffer,
    size_t size
) {
    static readlinkat_fn real_readlinkat = NULL;

    if (real_readlinkat == NULL) {
        real_readlinkat = (readlinkat_fn)dlsym(RTLD_NEXT, "readlinkat");
        if (real_readlinkat == NULL) {
            errno = ENOSYS;
            return -1;
        }
    }
    if (is_current_pid_exe(path)) {
        return real_readlinkat(
            AT_FDCWD,
            "/proc/self/exe",
            buffer,
            size
        );
    }
    return real_readlinkat(directory_fd, path, buffer, size);
}

